import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,viewFor,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const hostagePhysicalScenarios=['hostage-hidden','hostage-public','hostage-multi','hostage-late','hostage-counter','hostage-follower','hostage-third','hostage-cham','hostage-reveal','hostage-cham-decline','hostage-unrelated','hostage-suppressed','hostage-stopped','hostage-vanmil','hostage-fate','hostage-refill','hostage-wrong-user','hostage-wrong-attacker','hostage-decline'] as const;
export type HostagePhysicalScenario=typeof hostagePhysicalScenarios[number];
export function isHostagePhysicalScenario(name:string):name is HostagePhysicalScenario{return (hostagePhysicalScenarios as readonly string[]).includes(name);}
export function hostageMode(name:HostagePhysicalScenario){const late=name==='hostage-late',multi=name==='hostage-multi',follower=name==='hostage-follower'||name==='hostage-third',prior=['hostage-suppressed','hostage-stopped','hostage-vanmil'].includes(name),respond=['hostage-cham','hostage-reveal','hostage-suppressed','hostage-vanmil'].includes(name);return {late,multi,follower,prior,respond,owner:late||name==='hostage-third'||name==='hostage-counter'?3:1,attack:multi?'a2-p10-r1c3':late||name==='hostage-counter'?'a2-p10-r2c1':'a2-p24-r1c2'};}
/** Real setup, prior CHANTs, status attacks or ritual/suppression; no status, faction change or response is injected. */
export function makeHostagePhysicalScenario(name:HostagePhysicalScenario,players:{id:string;name:string}[]){
 const m=hostageMode(name);let s=createGame(players,entropy(),{startingSeat:m.prior?3:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,[name==='hostage-wrong-attacker'?'魔導王ガイナス':'侍大将のシン',name==='hostage-counter'?'早駆けのランカスター':name==='hostage-wrong-user'?'大神官ジル':'黒騎士ガーウィン',name==='hostage-unrelated'?'有翼人のティア':'小妖精のチャム',name==='hostage-vanmil'?'邪祭ウーノス':'占星術師のアルセイル'][i]!);for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:2};if(m.prior&&name!=='hostage-vanmil')s.players[c]!.permanent!.spirit=2-gameStats(s,c).spirit;
 const keep=[takeCard(s,a,m.attack),takeCard(s,a,'a2-p24-r2c2'),takeCard(s,players[m.owner]!.id,'a2-p02-r2c2'),takeCard(s,d,'a2-p02-r2c3')],wood=m.follower?takeCard(s,b,'兵士'):undefined;if(wood)keep.push(wood);if(name==='hostage-counter')keep.push(takeCard(s,b,'a2-p10-r3c3'));const prior=m.prior?takeCard(s,d,name==='hostage-vanmil'?'復活の儀式':name==='hostage-stopped'?'a2-p13-r2c1':'a2-p13-r1c2'):undefined;if(prior)keep.push(prior);for(const p of players)trimHand(s,p.id,...keep);let blood:string|undefined;if(name==='hostage-refill'){blood=takeCard(s,a,'a2-p01-r1c3');s.players[a]!.hand=s.players[a]!.hand.filter(id=>id!==blood);}const ordinary=s.deck.filter(id=>getAction(id)!.category!=='open'),opens=s.deck.filter(id=>getAction(id)!.category==='open');s.deck=blood?[blood,...ordinary,...opens]:[...ordinary,...opens];s.events=[];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`HOSTAGE_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('HOSTAGE_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('HOSTAGE_FIXTURE_CARDS');}
 function settle(){for(let n=0;n<300;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('HOSTAGE_FIXTURE_WINDOW');}
 function start(id:string){act(id,{type:'START_TURN'});settle();act(id,{type:'CHOOSE_DRAW',draw:false});settle();}
 function end(id:string){if(s.phase==='action')act(id,{type:'PASS_ACTION'});if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>!keep.includes(x)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});settle();}
 for(const id of [a,b,c,d]){if(id===b&&wood)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:wood});act(id,{type:'PASS_SETUP'});}start(m.prior?d:a);if(m.prior||['hostage-cham','hostage-cham-decline','hostage-unrelated'].includes(name)){act(c,{type:'REVEAL_CHARACTER'});settle();}
 if(prior){if(name==='hostage-vanmil'){act(d,{type:'USE_REVIVAL_RITUAL'});settle();const o=viewFor(s,d).abilityOptions.find(o=>o.abilityId==='c2-p07-r1c2-ab03')!;act(d,{type:'USE_ABILITY',abilityId:o.abilityId,targetEventId:o.targetEventId,targetIds:[c]});settle();if(!s.suppressionDesignations?.some(x=>x.targetId===c))throw Error('HOSTAGE_FIXTURE_SUPPRESSION');}else{act(d,{type:'ATTACK',cardInstanceId:prior,targetIds:[c],dedicated:false});settle();if(!s.players[c]!.statuses?.some(x=>x.kind===(name==='hostage-stopped'?'stopped':'ability-disabled')))throw Error('HOSTAGE_FIXTURE_STATUS');}end(d);start(a);}
 if(name==='hostage-public'){act(a,{type:'REVEAL_CHARACTER'});settle();}if(m.multi||m.late||name==='hostage-counter'){act(a,{type:'CHANT',cardInstanceId:m.attack});end(a);for(const id of [b,c,d]){start(id);end(id);}start(a);}if(blood&&s.deck[0]!==blood)throw Error('HOSTAGE_FIXTURE_BLOOD');return s;
}
